import {
  selectConversationForSelectedElement,
  selectStackToShow,
  useInspectorStore,
} from "../store";
import { selectIsMantleEngine } from "../store/selectors";
import { FlowSection } from "./FlowSection";
import { SkillSection } from "./SkillSection";

/**
 * Engine-specific middle pane: skill-based (Mantle) projects render the
 * active skill document, flow-based (v1) projects the flow canvas. Owning
 * the fork (and the flow-view store reads) here keeps the layout component
 * engine-agnostic.
 */
export function MiddlePane() {
  const isMantleEngine = useInspectorStore(selectIsMantleEngine);
  const stackToShow = useInspectorStore(selectStackToShow);
  const conversationList = useInspectorStore((s) => s.conversationList);
  const conversationForSelectedElement = useInspectorStore(selectConversationForSelectedElement);
  const flows = useInspectorStore((s) => s.flows);
  const flowsLoading = useInspectorStore((s) => s.flowsLoading);
  const flowsError = useInspectorStore((s) => s.flowsError);

  if (isMantleEngine) {
    return <SkillSection />;
  }
  return (
    <FlowSection
      stackToShow={stackToShow}
      conversationList={conversationList}
      conversationForSelectedElement={conversationForSelectedElement}
      flows={flows}
      flowsLoading={flowsLoading}
      flowsError={flowsError}
    />
  );
}
